import{_ as o,o as a,c as n,ae as s}from"./chunks/framework.YL6nI5ZP.js";const p=JSON.parse('{"title":"Las Modificaciones de HydroCouple al Motor SWMM de la US EPA: el motor OpenSWMM y sus extensiones","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/modificaciones-motor/01-introduccion-y-reescritura.md","filePath":"es/explanation/modificaciones-motor/01-introduccion-y-reescritura.md"}'),i={name:"es/explanation/modificaciones-motor/01-introduccion-y-reescritura.md"};function c(r,e,t,d,l,u){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="las-modificaciones-de-hydrocouple-al-motor-swmm-de-la-us-epa-el-motor-openswmm-y-sus-extensiones" tabindex="-1">Las Modificaciones de HydroCouple al Motor SWMM de la US EPA: el motor OpenSWMM y sus extensiones <a class="header-anchor" href="#las-modificaciones-de-hydrocouple-al-motor-swmm-de-la-us-epa-el-motor-openswmm-y-sus-extensiones" aria-label="Permalink to &quot;Las Modificaciones de HydroCouple al Motor SWMM de la US EPA: el motor OpenSWMM y sus extensiones&quot;">​</a></h1><p><em>Documento de Referencia Técnica — Agosto 2026</em></p><p><em>Fuente original (LaTeX): <a href="./../../../sources/modificaciones_openswmm.tex">docs/sources/modificaciones_openswmm.tex</a></em></p><blockquote><p>Este documento describe, a nivel de ecuaciones y de diseño, el trabajo que el grupo <strong>HydroCouple</strong> ha realizado sobre el motor de simulación hidráulica <strong>SWMM</strong> de la <strong>U.S. Environmental Protection Agency</strong> (US EPA). El motor <strong>OpenSWMM</strong> no es una modificación puntual del código C del SWMM 5.x oficial: es una reescritura moderna en C++ que persigue dos objetivos simultáneos: (i) <em>paridad bit a bit</em> con el motor EPA para las funcionalidades estándar, y (ii) una capa de <em>extensiones numéricas y de plataforma</em> que el motor oficial no posee. Este documento se enfoca en esa segunda capa: la formulación semi-implícita de continuidad de nodo, la aceleración de Anderson del ciclo de Picard, la ranura de Preissmann dinámica, las uniones virtuales, el solver 1D explícito de volúmenes finitos, el módulo 2D con acoplamiento 1D–2D, la recuperación física del RDII, el paralelismo OpenMP bit-exacto y los cambios de comportamiento por defecto.</p></blockquote><h2 id="introduccion" tabindex="-1">Introducción <a class="header-anchor" href="#introduccion" aria-label="Permalink to &quot;Introducción&quot;">​</a></h2><h3 id="contexto-openswmm-y-su-relacion-con-swmm-de-la-us-epa" tabindex="-1">Contexto: OpenSWMM y su relación con SWMM de la US EPA <a class="header-anchor" href="#contexto-openswmm-y-su-relacion-con-swmm-de-la-us-epa" aria-label="Permalink to &quot;Contexto: OpenSWMM y su relación con SWMM de la US EPA&quot;">​</a></h3><p>El SWMM (<em>Storm Water Management Model</em>) es el modelo de gestión de aguas lluvias y aguas servidas de la US EPA. Su motor hidráulico 1D (SWMM 5.x) resuelve las ecuaciones de de Saint-Venant sobre una red de nodos y enlaces con tres formulaciones de tránsito (escurrimiento permanente, onda cinemática y onda dinámica), y ha evolucionado lentamente desde la década de 1970.</p><p>El proyecto <strong>OpenSWMM</strong> (motor <code>openswmm.engine</code>), liderado por HydroCouple, reimplementa ese motor desde cero en C++ moderno con dos principios de diseño:</p><ol><li><strong>Paridad bit a bit</strong> con el motor EPA para las funcionalidades estándar: cada término aritmético de los solvers clásicos reproduce exactamente el orden de operaciones y los valores del código legado (por ejemplo, el exponente <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1.33333</mn></mrow><annotation encoding="application/x-tex">1.33333</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1.33333</span></span></span></span> de la fricción de Manning, los factores de conversión truncados, la agrupación de operaciones en coma flotante). Esto se valida con una batería de pruebas de regresión contra el motor original y con <em>soluciones manufacturadas</em>.</li><li><strong>Una capa de extensiones</strong>: algoritmos numéricos nuevos y opciones que el SWMM oficial no posee, orientados a mejorar la estabilidad, la convergencia y la fidelidad física de los transitorios, junto con arquitecturas de cómputo modernas (paralelismo, GPU, WebAssembly).</li></ol><p>Este documento se ocupa exclusivamente de la segunda capa. Las secciones siguientes describen cada extensión con sus ecuaciones, su motivación y su sintaxis de entrada. Todas las referencias de código apuntan al directorio <code>src/engine/</code> del motor (<code>hydraulics/</code>, <code>hydraulics/fv/</code>, <code>2d/</code> y <code>hydrology/</code>).</p><h3 id="la-reescritura-arquitectonica-como-base" tabindex="-1">La reescritura arquitectónica como base <a class="header-anchor" href="#la-reescritura-arquitectonica-como-base" aria-label="Permalink to &quot;La reescritura arquitectónica como base&quot;">​</a></h3><p>Aunque no es una &quot;extensión&quot; funcional, la reescritura es el habilitador de todo lo demás. Las decisiones arquitectónicas clave son:</p><ul><li><strong>Almacenamiento orientado a columnas (SoA)</strong>: los datos de nodos y enlaces se almacenan como arreglos paralelos (<code>NodeData.hpp</code>, <code>LinkData.hpp</code>), lo que permite accesos contiguos a caché y vectorización SIMD en los bucles internos.</li><li><strong>Geometría por lotes</strong>: la clase <code>XSectGroups</code> (<code>XSectBatch.cpp</code>) agrupa los conductos por forma geométrica y calcula áreas, radios hidráulicos y espejos de agua de todos los conductos en pasadas vectorizables, sin despacho por forma dentro del bucle interno.</li><li><strong>Núcleos de momentum por categoría</strong>: cada conducto se clasifica una vez por iteración en una categoría (seco, Manning a superficie libre, cerrado a sección llena, impulsión por Hazen–Williams o por Darcy–Weisbach) y se despacha a un núcleo sin ramas.</li><li><strong>Paralelismo OpenMP bit-exacto</strong>: el ciclo de Picard completo corre dentro de una única región <code>omp parallel</code> (equipo persistente), con un <code>THREADS n</code> en <code>[OPTIONS]</code>. La exactitud bit a bit a cualquier número de hilos se garantiza por diseño: cada bucle paralelo escribe elementos disjuntos (un solo productor por elemento), y el único combine entre hilos es un contador entero de nodos no convergidos, libre de orden. El barrido de caudales hacia los nodos se hace mediante una adyacencia CSR nodo→conducto que reproduce exactamente el orden de acumulación en coma flotante del barrido serial (<code>buildConduitNodeCSR</code>).</li></ul>',13)])])}const g=o(i,[["render",c]]);export{p as __pageData,g as default};
